//! Saving data generated by the frontend (e.g. the trend chart history) to a user-chosen file.

use std::fs;

use serde_json::{json, Value};
use tauri::AppHandle;
use tauri_plugin_dialog::DialogExt;
use tokio::sync::oneshot;

use crate::{
    decoders::{fail, ok_with},
    send_log,
};

#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportCsvArgs {
    content: String,
    file_name: String,
}

#[tauri::command]
pub async fn export_csv(app: AppHandle, args: ExportCsvArgs) -> Result<Value, ()> {
    let (tx, rx) = oneshot::channel();
    app.dialog()
        .file()
        .set_title("Export CSV")
        .set_file_name(&args.file_name)
        .add_filter("CSV Files", &["csv"])
        .save_file(move |path| {
            let _ = tx.send(path);
        });

    let Some(target) = rx.await.ok().flatten().and_then(|p| p.into_path().ok()) else {
        return Ok(fail("Cancelled"));
    };

    Ok(match fs::write(&target, args.content) {
        Ok(()) => {
            send_log(&app, format!("Exported CSV → {}", target.display()));
            ok_with(json!({}))
        }
        Err(e) => fail(e),
    })
}
